-- Add AI section to VAL-RULES (insert after existing slides)
INSERT INTO acc_training_slides (course_id, title, content, slide_type, order_index, interactive_config) VALUES
(7, 'AI Rule Suggester: Hands-On', '<h2>Using AI to Generate Rules</h2><p>The AI Suggester is accessible from every field card (sparkle/AI button). Here''s exactly how it works:</p><ol><li>Click the <strong>AI sparkle icon</strong> on any field card</li><li>Modal opens showing field context (name, type, existing rules)</li><li>AI generates 2-5 suggestions with confidence percentages</li><li>Each suggestion shows: rule type, range/pattern, severity, message</li><li>Click <strong>Accept</strong> to create the rule instantly</li><li>Click <strong>Modify</strong> to adjust before creating</li><li>Click <strong>Reject</strong> to skip that suggestion</li></ol><p><strong>What AI considers:</strong></p><ul><li>Field name semantics (e.g., "Heart Rate" → vital sign range)</li><li>Field data type (number → range check, text → format check)</li><li>Other fields in the form (cross-field comparisons)</li><li>Common clinical data patterns from training data</li></ul><p><strong>Best used for:</strong> New forms where you want a quick starting set of rules. Review each suggestion critically — AI may suggest ranges that don''t match your protocol.</p>', 'text', 16),
(7, 'Exercise: Use AI to Suggest Rules', '', 'interactive', 17,
'{"type":"scenario","instruction":"You just created a new Vital Signs form with fields: Systolic BP, Diastolic BP, Heart Rate, Temperature, Weight. You click the AI button on the Systolic BP field. What should you expect?","data":{"context":"The AI Suggester modal opens for Systolic Blood Pressure (Number field).","choices":[{"text":"AI suggests a text format check (email pattern)","correct":false,"feedback":"Incorrect. AI recognizes this is a numeric vital sign field, not a text field. It would suggest range checks."},{"text":"AI suggests range 60-250 mmHg with Create Query severity and a cross-field check that SBP > DBP","correct":true,"feedback":"Correct! AI recognizes systolic BP as a vital sign, suggests appropriate clinical range, and identifies the cross-field relationship with diastolic BP."},{"text":"AI suggests making the field required only","correct":false,"feedback":"While AI might include a required check, it would primarily suggest clinical range validation for a vital sign field."},{"text":"AI cannot analyze vital sign fields","correct":false,"feedback":"AI is especially good at vital sign fields because they have well-established clinical ranges."}]},"successMessage":"AI excels at suggesting clinically appropriate ranges and cross-field checks for vital signs!"}');

