-- ============================================================
INSERT INTO acc_training_slides (course_id, title, content, slide_type, order_index, interactive_config) VALUES
(8, 'Exercise: Respond to a Query (Hands-On)', '', 'interactive', 19,
'{"type":"fill-form","instruction":"A monitor raised a query: ''Weight recorded as 750 kg. Please verify and correct.'' The source document shows the patient weighs 75 kg. Respond to the query:","data":{"fields":[{"label":"Your Response","type":"text","correctAnswer":"any","placeholder":"Explain what happened (e.g., transcription error, extra zero)...","hint":"Reference the source document and explain the discrepancy"},{"label":"Proposed Corrected Value (kg)","type":"number","correctAnswer":"75","placeholder":"Enter the correct weight"},{"label":"Source Document Reference","type":"text","correctAnswer":"any","placeholder":"e.g., Patient chart page 12, vital signs entry dated 2026-04-15"}]},"successMessage":"Correct! You identified the transcription error and proposed the correct value of 75 kg.","hintMessage":"The source shows 75 kg. The entry of 750 was a typo (extra zero)."}'),
(8, 'Exercise: Create a Query (Hands-On)', '', 'interactive', 20,
'{"type":"fill-form","instruction":"You are monitoring a patient record and notice Heart Rate = 30 bpm which seems very low. Create a query on this field:","data":{"fields":[{"label":"Query Subject","type":"text","correctAnswer":"any","placeholder":"e.g., Heart Rate value appears unusually low"},{"label":"Severity","type":"dropdown","options":["Critical","Major","Minor"],"correctAnswer":"Major","hint":"30 bpm is very low but not impossible (athletic bradycardia)"},{"label":"Description","type":"text","correctAnswer":"any","placeholder":"Describe the concern and what you need the site to verify..."},{"label":"Assign To","type":"dropdown","options":["Site Coordinator","Investigator","Data Manager"],"correctAnswer":"Site Coordinator","hint":"Site staff should verify against source documents"}]},"successMessage":"Query created! The site coordinator will verify against source documents and respond.","hintMessage":"Severity should be Major (unusual but possible). Assign to Site Coordinator who can check source docs."}');

-- PATIENT-MGMT: Add more detail
INSERT INTO acc_training_slides (course_id, title, content, slide_type, order_index, interactive_config) VALUES
(6, 'Patient Detail: Editing and Managing', '<h2>Working with Patient Records</h2><p><strong>The Patient Detail View shows:</strong></p><ul><li><strong>Header:</strong> Subject ID, status badge, enrollment date, assigned site, study arm</li><li><strong>Visit Timeline:</strong> Horizontal row of visit columns (Screening, Baseline, Week 4...)</li><li><strong>Form Chips:</strong> Colored chips within each visit column representing assigned CRFs</li><li><strong>Progress Bar:</strong> Overall form completion percentage</li></ul><p><strong>Form Chip Actions (click a chip):</strong></p><ul><li>Gray chip → Opens blank form for data entry</li><li>Blue chip → Opens in-progress form to continue entry</li><li>Green chip → Opens completed form for review</li><li>Purple chip → Opens signed form (read-only unless unlock requested)</li></ul><p><strong>Patient Actions (header buttons):</strong></p><ul><li><strong>Add Unscheduled Visit</strong> — for adverse events, early termination</li><li><strong>Transfer Patient</strong> — move to different site</li><li><strong>Withdraw Patient</strong> — mark as withdrawn (preserves all data)</li><li><strong>View Audit Trail</strong> — see all changes to this patient''s data</li></ul>', 'text', 16, NULL),
(6, 'Exercise: Navigate a Patient Record', '', 'interactive', 17,
'{"type":"scenario","instruction":"A patient (SUBJ-042) needs their Week 4 Vital Signs form completed. How do you get there?","data":{"context":"You are logged in as a Coordinator. You need to enter vital signs data for patient SUBJ-042 at their Week 4 visit.","choices":[{"text":"Go to Forms page → find Vital Signs → enter data","correct":false,"feedback":"The Forms page manages form TEMPLATES, not patient data. You need to go through the Patients page."},{"text":"Go to Patients → search SUBJ-042 → click patient → find Week 4 column → click Vital Signs chip","correct":true,"feedback":"Correct! Always navigate through Patients → specific patient → visit column → form chip to enter data."},{"text":"Go to Studies → select the study → enter data","correct":false,"feedback":"Studies page manages study configuration, not individual patient data entry."},{"text":"Go to My Tasks and wait for it to appear","correct":false,"feedback":"My Tasks shows assigned work but the form might not be a task yet. Direct navigation is: Patients → Patient → Visit → Form."}]},"successMessage":"Navigate through: Patients → Search → Patient Detail → Visit Column → Form Chip!"}');

COMMIT;
